function dva=pix2dva(pix, scr)% conversion of degree of visual angle into pixels % inputs :%	va		: x degrees of visual angle%	monitor	: structure describing monitor characteristics. Minimal fields required are listed below%		monitor.subjectDistance	: viewing distance [mm]%		monitor.width       	: physical width of monitor [mm]%		monitor.ResX			: x resolution of monitor dva = atan(pix*(scr.width/scr.resX)/scr.subDist)*180/pi;